1	import { useState, useRef, DragEvent, ChangeEvent, useEffect } from "react";
2	import { Upload, FileText, CheckCircle, Camera, Plus, X } from "lucide-react";
3	import { Input } from "@/shared/ui/input";
4	import { Button } from "@/shared/ui/button";
5	import { cn } from "@/shared/lib/utils";
6	import { useIsMobile } from "@/shared/hooks/use-mobile";
7	import { useHasCamera } from "@/shared/hooks/use-mobile";
8	import { toast } from "sonner";
9	import { wideError } from '@/shared/lib/telemetry/wide-events';
10	import {
11	  fileToDownscaledFile,
12	  NF_RECOVERY_MAX_DIM,
13	  NF_RECOVERY_JPEG_QUALITY,
14	} from "@/features/notas-fiscais/lib/downscaleImage";
15	import {
16	  savePendingCapture,
17	  setPendingCaptureFlag,
18	  clearPendingCaptureFlag,
19	} from "@/features/notas-fiscais/lib/pendingCapture";
20	
21	interface DragDropUploadAreaProps {
22	  onFileSelect: (file: File) => void;
23	  selectedFile: File | null;
24	  onFilesSelect?: (files: File[]) => void;
25	  selectedFiles?: File[];
26	  multiple?: boolean;
27	  accept?: string;
28	  disabled?: boolean;
29	}
30	
31	/**
32	 * Garante que imagens sejam reduzidas (≤3200px, JPEG 0.95) antes de entrar no
33	 * state da página. PDFs passam intactos — pdf.js cuida do downscale por página
34	 * no `processImage`/`pdfToImageBase64Pages`.
35	 *
36	 * PORQUÊ: a foto crua de câmera mobile (≈4000×3000, ~10MB de dataURL ao
37	 * decodificar) é o pico que matava o WebView Android. Reduzir na ORIGEM —
38	 * antes do File entrar em selectedFile/selectedFiles — limita o pico e elimina
39	 * cópias gigantes em memória. A resolução fica alta (3200px) porque o OCR lê
40	 * essa imagem (subida pro bucket); o pico de memória continua sendo o decode da
41	 * foto crua, não o output — então qualidade alta não reabre o OOM.
42	 */
43	async function downscaleIfImage(file: File): Promise<File> {
44	  if (!file.type.startsWith('image/')) return file;
45	  try {
46	    return await fileToDownscaledFile(file);
47	  } catch (error) {
48	    wideError('dragDropUpload.downscaleImagem', 'Erro ao reduzir imagem; mantendo arquivo original como fallback', {
49	      attributes: {
50	        'error.message': String((error as Error)?.message || error),
51	        'operation.name': 'downscaleAtSource',
52	        'file.name': file.name,
53	        'file.type': file.type,
54	        'file.size': file.size,
55	      },
56	    });
57	    return file;
58	  }
59	}
60	
61	/**
62	 * Persiste em localStorage uma cópia LEVE da foto (NF_RECOVERY_*), pra restore
63	 * caso o Android mate o WebView antes do upload. Menor que a versão do OCR de
64	 * propósito — a hi-q estouraria a quota. Best-effort: falha é silenciosa.
65	 */
66	async function persistRecoveryCopy(file: File): Promise<void> {
67	  try {
68	    const light = await fileToDownscaledFile(
69	      file,
70	      file.name,
71	      NF_RECOVERY_MAX_DIM,
72	      NF_RECOVERY_JPEG_QUALITY,
73	    );
74	    await savePendingCapture(light);
75	  } catch {
76	    /* recovery é defesa em profundidade — sem cópia leve, segue o fluxo normal */
77	  }
78	}
79	
80	export const DragDropUploadArea = ({
81	  onFileSelect,
82	  selectedFile,
83	  onFilesSelect,
84	  selectedFiles = [],
85	  multiple = false,
86	  accept = 'image/*',
87	  disabled = false,
88	}: DragDropUploadAreaProps) => {
89	  const [isDragOver, setIsDragOver] = useState(false);
90	  const [isHovering, setIsHovering] = useState(false);
91	  const fileInputRef = useRef<HTMLInputElement>(null);
92	  const cameraInputRef = useRef<HTMLInputElement>(null);
93	  // Guarda anti-double-click; o flag durável (localStorage) é setado em paralelo
94	  // por setPendingCaptureFlag e serve ao hook de boot que redireciona pra NF.
95	  const isCapturing = useRef(false);
96	
97	  // Limpa o flag durável quando o usuário volta pro WebView (focus) — cobre o
98	  // caso de o usuário ter aberto a câmera e cancelado sem tirar foto. O flag
99	  // tem TTL próprio, isso é só a faxina best-effort no caminho feliz.
100	  useEffect(() => {
101	    const onFocus = () => {
102	      if (isCapturing.current) {
103	        // Pequeno delay: em alguns devices o onchange do input chega DEPOIS
104	        // do focus; se a foto vier, savePendingCapture cuida do flag.
105	        setTimeout(() => {
106	          if (isCapturing.current) {
107	            clearPendingCaptureFlag();
108	            isCapturing.current = false;
109	          }
110	        }, 1500);
111	      }
112	    };
113	    window.addEventListener('focus', onFocus);
114	    return () => window.removeEventListener('focus', onFocus);
115	  }, []);
116	
117	  const handleDragEnter = (e: DragEvent<HTMLDivElement>) => {
118	    e.preventDefault();
119	    e.stopPropagation();
120	    if (!disabled) {
121	      setIsDragOver(true);
122	    }
123	  };
124	
125	  const handleDragLeave = (e: DragEvent<HTMLDivElement>) => {
126	    e.preventDefault();
127	    e.stopPropagation();
128	
129	    const rect = e.currentTarget.getBoundingClientRect();
130	    const x = e.clientX;
131	    const y = e.clientY;
132	
133	    if (x < rect.left || x > rect.right || y < rect.top || y > rect.bottom) {
134	      setIsDragOver(false);
135	    }
136	  };
137	
138	  const handleDragOver = (e: DragEvent<HTMLDivElement>) => {
139	    e.preventDefault();
140	    e.stopPropagation();
141	  };
142	
143	  const handleDrop = async (e: DragEvent<HTMLDivElement>) => {
144	    e.preventDefault();
145	    e.stopPropagation();
146	    setIsDragOver(false);
147	
148	    if (disabled) return;
149	
150	    const files = Array.from(e.dataTransfer.files);
151	    if (files.length === 0) return;
152	    const validFiles = files.filter(f => {
153	      if (accept === 'image/*') return f.type.startsWith('image/');
154	      return accept.split(',').some(a => {
155	        const pat = '^' + a.trim().replace(/[.+?^${}()|[\]\\]/g, '\\$&').replace('\\*', '.*') + '$';
156	        return new RegExp(pat).test(f.type);
157	      });
158	    });
159	    if (validFiles.length === 0) return;
160	
161	    // Downscale de imagens na entrada — vale tanto pro mobile (galeria) quanto
162	    // pra desktop (drag/drop): mantém o pipeline de memória previsível.
163	    const processed = await Promise.all(validFiles.map(downscaleIfImage));
164	
165	    if (multiple && onFilesSelect) {
166	      const merged = [...selectedFiles, ...processed].slice(0, 2);
167	      onFilesSelect(merged);
168	    } else {
169	      onFileSelect(processed[0]);
170	    }
171	  };
172	
173	  const handleFileInputChange = async (e: ChangeEvent<HTMLInputElement>) => {
174	    const files = e.target.files;
175	    if (!files || files.length === 0) {
176	      e.target.value = '';
177	      return;
178	    }
179	    const inputFiles = Array.from(files);
180	    const processed = await Promise.all(inputFiles.map(downscaleIfImage));
181	    if (multiple && onFilesSelect) {
182	      const merged = [...selectedFiles, ...processed].slice(0, 2);
183	      onFilesSelect(merged);
184	    } else {
185	      onFileSelect(processed[0]);
186	    }
187	    // Reset value para permitir re-seleção do mesmo arquivo
188	    e.target.value = '';
189	  };
190	
191	  const isMobile = useIsMobile();
192	  const { hasCamera, isChecking } = useHasCamera();
193	
194	  const handleClick = () => {
195	    if (disabled) return;
196	    if (isCapturing.current) return;
197	    // Se já tem 2 arquivos no multi-mode, não abrir seleção (limite atingido)
198	    if (multiple && selectedFiles.length >= 2) return;
199	    if (isMobile && hasCamera) {
200	      setPendingCaptureFlag();
201	      isCapturing.current = true;
202	      cameraInputRef.current?.click();
203	      return;
204	    }
205	    fileInputRef.current?.click();
206	  };
207	
208	  const handleCameraClick = (e: React.MouseEvent) => {
209	    e.stopPropagation();
210	    if (!disabled && hasCamera && !isCapturing.current) {
211	      setPendingCaptureFlag();
212	      isCapturing.current = true;
213	      cameraInputRef.current?.click();
214	    }
215	  };
216	
217	  const handleCameraCapture = async (e: ChangeEvent<HTMLInputElement>) => {
218	    const files = e.target.files;
219	    const raw = files && files.length > 0 ? files[0] : null;
220	    // Sempre limpa o flag — recebemos retorno do input (com ou sem foto).
221	    clearPendingCaptureFlag();
222	    isCapturing.current = false;
223	    if (!raw) {
224	      e.target.value = '';
225	      return;
226	    }
227	
228	    // PORQUÊ downscale ANTES de entregar via onFileSelect: o File cru de câmera
229	    // de Android costuma ter 5-10MB e segura um pico de ~13MB de dataURL ao
230	    // decodificar. Esse pico era o gatilho do OOM que matava o WebView. Aqui
231	    // reduzimos para a versão hi-q do OCR (≤3200px, JPEG 0.95) e removemos a foto
232	    // crua do alcance do GC sem cópias intermediárias. Essa imagem será subida
233	    // pro bucket no processImage — o OCR a lê de lá, sem base64 grande no cliente.
234	    const downscaled = await downscaleIfImage(raw);
235	
236	    if (multiple && onFilesSelect) {
237	      // Multi-mode não persiste em localStorage (restore não suporta multi).
238	      const merged = [...selectedFiles, downscaled].slice(0, 2);
239	      onFilesSelect(merged);
240	      toast.success(`Foto ${merged.length} capturada com sucesso!`);
241	    } else {
242	      onFileSelect(downscaled);
243	      toast.success("Foto capturada com sucesso!");
244	      // Defesa em profundidade: persiste uma cópia LEVE em localStorage pra
245	      // permitir restore caso o Android mate o WebView antes do upload (a hi-q
246	      // estouraria a quota). Falha aqui é silenciosa por design.
247	      void persistRecoveryCopy(downscaled);
248	    }
249	
250	    e.target.value = '';
251	  };
252	
253	  return (
254	    <div
255	      className={cn(
256	        'relative border-2 border-dashed rounded-lg p-4 sm:p-8 text-center transition-all duration-300 cursor-pointer',
257	        'hover:border-primary/50 hover:bg-primary/5',
258	        {
259	          'border-primary bg-primary/10 shadow-lg scale-[1.02]': isDragOver,
260	          'border-company-light': !isDragOver && !selectedFile && selectedFiles.length === 0,
261	          'border-green-400 bg-green-50': (selectedFile || selectedFiles.length > 0) && !isDragOver,
262	          'opacity-50 cursor-not-allowed': disabled,
263	          'transform hover:scale-[1.01]': !disabled && isHovering,
264	        },
265	      )}
266	      onDragEnter={handleDragEnter}
267	      onDragLeave={handleDragLeave}
268	      onDragOver={handleDragOver}
269	      onDrop={handleDrop}
270	      onClick={handleClick}
271	      onMouseEnter={() => setIsHovering(true)}
272	      onMouseLeave={() => setIsHovering(false)}
273	    >
274	      {/* Efeito de brilho quando em drag over */}
275	      {isDragOver && (
276	        <div
277	          className="absolute inset-0 bg-gradient-to-r from-blue-400/20 via-purple-400/20 to-blue-400/20 rounded-lg"
278	          style={{ animation: 'pulse 3s ease-in-out infinite' }}
279	        />
280	      )}
281	
282	      {/* Círculos animados quando em drag over */}
283	      {isDragOver && (
284	        <>
285	          <div
286	            className="absolute top-4 left-4 w-3 h-3 bg-primary/40 rounded-full"
287	            style={{
288	              animation: 'bounce 2s ease-in-out infinite',
289	              animationDelay: '0s',
290	            }}
291	          />
292	          <div
293	            className="absolute top-4 right-4 w-3 h-3 bg-primary/40 rounded-full"
294	            style={{
295	              animation: 'bounce 2s ease-in-out infinite',
296	              animationDelay: '0.5s',
297	            }}
298	          />
299	          <div
300	            className="absolute bottom-4 left-4 w-3 h-3 bg-primary/40 rounded-full"
301	            style={{
302	              animation: 'bounce 2s ease-in-out infinite',
303	              animationDelay: '1s',
304	            }}
305	          />
306	          <div
307	            className="absolute bottom-4 right-4 w-3 h-3 bg-primary/40 rounded-full"
308	            style={{
309	              animation: 'bounce 2s ease-in-out infinite',
310	              animationDelay: '1.5s',
311	            }}
312	          />
313	        </>
314	      )}
315	
316	      <div className="relative z-10">
317	        {/* Multi-file mode: show list of selected files */}
318	        {multiple && selectedFiles.length > 0 ? (
319	          <div className="space-y-3 sm:space-y-4">
320	            <div className="flex items-center justify-center">
321	              <div className="w-12 h-12 sm:w-16 sm:h-16 bg-green-100 rounded-full flex items-center justify-center">
322	                <CheckCircle className="w-6 h-6 sm:w-8 sm:h-8 text-green-600" />
323	              </div>
324	            </div>
325	            <div className="space-y-2">
326	              <p className="text-base sm:text-lg font-semibold text-green-700">
327	                {selectedFiles.length === 1 ? '1 página selecionada' : `${selectedFiles.length} páginas selecionadas`}
328	              </p>
329	              {selectedFiles.map((f, idx) => (
330	                <div key={idx} className="flex items-center justify-center gap-2 text-sm text-green-600">
331	                  <FileText className="h-3.5 w-3.5 flex-shrink-0" />
332	                  <span className="font-medium truncate max-w-[200px]">Pág. {idx + 1}: {f.name}</span>
333	                  <span className="text-xs text-muted-foreground">({(f.size / 1024 / 1024).toFixed(2)} MB)</span>
334	                  <button
335	                    type="button"
336	                    className="p-0.5 rounded-full hover:bg-red-100 text-red-400 hover:text-red-600 transition-colors"
337	                    onClick={(e) => {
338	                      e.stopPropagation();
339	                      const updated = selectedFiles.filter((_, i) => i !== idx);
340	                      onFilesSelect?.(updated);
341	                    }}
342	                  >
343	                    <X className="h-3.5 w-3.5" />
344	                  </button>
345	                </div>
346	              ))}
347	              {selectedFiles.length < 2 && (
348	                <div className="pt-2 flex items-center justify-center gap-2">
349	                  <Button
350	                    type="button"
351	                    variant="outline"
352	                    size="sm"
353	                    onClick={(e) => {
354	                      e.stopPropagation();
355	                      fileInputRef.current?.click();
356	                    }}
357	                    disabled={disabled}
358	                    className="gap-2 border-[#57715B]/30 text-[#57715B] hover:bg-[#57715B]/10 font-medium h-9 px-3 text-sm rounded-full"
359	                  >
360	                    <Plus className="h-4 w-4" />
361	                    Adicionar 2ª página
362	                  </Button>
363	                  {isMobile && hasCamera && !isChecking && (
364	                    <Button data-mia-action="camera-click"
365	                      type="button"
366	                      variant="outline"
367	                      size="sm"
368	                      onClick={handleCameraClick}
369	                      disabled={disabled}
370	                      className="gap-2 bg-primary/10 border-primary/30 hover:bg-primary/20 text-primary font-medium h-9 px-3 text-sm rounded-full"
371	                    >
372	                      <Camera className="h-4 w-4" />
373	                      Tirar 2ª foto
374	                    </Button>
375	                  )}
376	                </div>
377	              )}
378	            </div>
379	          </div>
380	        ) : selectedFile ? (
381	          <div className="space-y-3 sm:space-y-4">
382	            <div className="flex items-center justify-center">
383	              <div className="w-12 h-12 sm:w-16 sm:h-16 bg-green-100 rounded-full flex items-center justify-center">
384	                <CheckCircle className="w-6 h-6 sm:w-8 sm:h-8 text-green-600" />
385	              </div>
386	            </div>
387	            <div>
388	              <p className="text-base sm:text-lg font-semibold text-green-700 mb-2">
389	                Arquivo selecionado com sucesso!
390	              </p>
391	              <p className="text-sm text-green-600 font-medium truncate px-2">
392	                {selectedFile.name}
393	              </p>
394	              <p className="text-xs text-muted-foreground mt-1">
395	                {(selectedFile.size / 1024 / 1024).toFixed(2)} MB
396	              </p>
397	            </div>
398	          </div>
399	        ) : (
400	          <div className="space-y-3 sm:space-y-4">
401	            <div className="flex items-center justify-center">
402	              <div
403	                className={cn(
404	                  'w-12 h-12 sm:w-16 sm:h-16 rounded-full flex items-center justify-center transition-all duration-300',
405	                  {
406	                    'bg-primary/20 scale-110': isDragOver,
407	                    'bg-company-light/20': !isDragOver,
408	                  },
409	                )}
410	              >
411	                {isDragOver ? (
412	                  <FileText
413	                    className={cn(
414	                      'w-6 h-6 sm:w-8 sm:h-8 transition-all duration-300',
415	                      'text-primary',
416	                    )}
417	                    style={{ animation: 'pulse 2.5s ease-in-out infinite' }}
418	                  />
419	                ) : (
420	                  <Upload className="w-6 h-6 sm:w-8 sm:h-8 text-company-medium" />
421	                )}
422	              </div>
423	            </div>
424	
425	            <div>
426	              {isDragOver ? (
427	                <div className="space-y-2">
428	                  <p
429	                    className="text-base sm:text-lg font-semibold text-primary"
430	                    style={{ animation: 'pulse 2.5s ease-in-out infinite' }}
431	                  >
432	                    Solte o arquivo aqui!
433	                  </p>
434	                  <p className="text-sm text-primary/80 px-2">
435	                    Estamos prontos para receber sua nota fiscal
436	                  </p>
437	                </div>
