473	
474	      <Input
475	        ref={fileInputRef}
476	        type="file"
477	        accept={accept}
478	        onChange={handleFileInputChange}
479	        className="hidden"
480	        disabled={disabled}
481	      />
482	
483	      {/* Input oculto para captura de câmera */}
484	      <input
485	        ref={cameraInputRef}
486	        type="file"
487	        accept="image/*,image/jpeg,image/jpg,image/png"
488	        capture="environment"
489	        onChange={handleCameraCapture}
490	        style={{ display: 'none' }}
491	        disabled={disabled}
492	        // Atributos específicos para melhor compatibilidade mobile
493	        autoComplete="off"
494	        tabIndex={-1}
495	        multiple={false}
