1	// Persistência durável da foto capturada em Notas Fiscais para sobreviver ao
2	// kill do WebView pelo Android (PWA via Vercel).
3	//
4	// PORQUÊ não sessionStorage: o WebView é morto pelo Android quando a câmera
5	// nativa fica em foreground; ao retornar, o processo é recriado e
6	// `sessionStorage` é apagado (é per-session). `localStorage` é persistido em
7	// disco pelo WebView e sobrevive ao kill.
8	//
9	// PORQUÊ não IndexedDB: aqui persistimos a CÓPIA LEVE de recovery (NF_RECOVERY_*,
10	// ~1500px/0.8 → algumas centenas de KB em base64), não a versão hi-q do OCR.
11	// Cabe folgado na quota típica de ~5MB do localStorage. Se ainda assim estourar,
12	// `savePendingCapture` degrada gracioso (limpa a chave e segue — o fluxo
13	// principal já tem o File em memória). Não vale o custo de polyfill de IndexedDB
14	// em testes nem a complexidade async pra uma foto por sessão.
15	
16	const KEY_PHOTO = 'nf-pending-capture-v1';
17	const KEY_FLAG = 'nf-pending-capture-flag-v1';
18	
19	/** TTL da captura pendente. Após 10 min é considerada irrecuperável. */
20	const PHOTO_TTL_MS = 10 * 60 * 1000;
21	/** TTL do flag "abri a câmera mas não voltei ainda" — curto e só serve pra
22	 * reabrir o modal de upload caso o usuário tenha cancelado a câmera. */
23	const FLAG_TTL_MS = 60 * 1000;
24	
25	interface StoredPhoto {
26	  dataUrl: string;
27	  name: string;
28	  mime: string;
29	  ts: number;
30	}
31	
32	/**
33	 * Acesso defensivo ao localStorage — alguns contextos (modo privado raro,
34	 * iframes sandboxed) podem lançar SecurityError no simples acesso ao objeto.
35	 */
36	function getStorage(): Storage | null {
37	  try {
38	    if (typeof window === 'undefined') return null;
39	    return window.localStorage;
40	  } catch {
41	    return null;
42	  }
43	}
44	
45	function readJson<T>(key: string): T | null {
46	  const storage = getStorage();
47	  if (!storage) return null;
48	  try {
49	    const raw = storage.getItem(key);
50	    if (!raw) return null;
51	    return JSON.parse(raw) as T;
52	  } catch {
53	    // JSON corrompido — apaga pra não envenenar futuras leituras.
54	    try {
55	      storage.removeItem(key);
56	    } catch {
57	      /* noop */
58	    }
59	    return null;
60	  }
61	}
62	
63	function dataUrlToFile(dataUrl: string, name: string, mime: string): File | null {
64	  try {
65	    const commaIdx = dataUrl.indexOf(',');
66	    if (commaIdx < 0) return null;
67	    const payload = dataUrl.slice(commaIdx + 1);
68	    const binary = atob(payload);
69	    const bytes = new Uint8Array(binary.length);
70	    for (let i = 0; i < binary.length; i++) {
71	      bytes[i] = binary.charCodeAt(i);
