168	/**
169	 * Extrai o primeiro objeto JSON balanceado de um texto.
170	 * Ignora chaves dentro de strings (respeita escapes). Retorna null se não encontrar.
171	 */
172	function extractBalancedJson(text: string): string | null {
173	  if (!text) return null;
174	  let start = -1;
175	  let depth = 0;
176	  let inString = false;
177	  let escape = false;
178	  for (let i = 0; i < text.length; i++) {
179	    const ch = text[i];
180	    if (escape) { escape = false; continue; }
181	    if (ch === '\\') { escape = true; continue; }
182	    if (ch === '"') { inString = !inString; continue; }
183	    if (inString) continue;
184	    if (ch === '{') {
185	      if (depth === 0) start = i;
186	      depth++;
187	    } else if (ch === '}') {
188	      depth--;
189	      if (depth === 0 && start !== -1) {
190	        return text.slice(start, i + 1);
191	      }
192	    }
193	  }
194	  return null;
195	}
