197	function tryParseAiJson(aiResponse: string): any {
198	  if (!aiResponse) return null;
199	  let cleaned = aiResponse.trim();
200	  if (cleaned.startsWith('```json')) {
201	    cleaned = cleaned.replace(/^```json\s*/, '').replace(/\s*```\s*$/, '');
202	  } else if (cleaned.startsWith('```')) {
203	    cleaned = cleaned.replace(/^```\s*/, '').replace(/\s*```\s*$/, '');
204	  }
205	  const balanced = extractBalancedJson(cleaned) ?? cleaned;
206	  const sanitized = balanced
207	    .replace(/,\s*,/g, ',')
208	    .replace(/,\s*}/g, '}')
209	    .replace(/,\s*]/g, ']');
210	  try {
211	    return JSON.parse(sanitized);
212	  } catch {
213	    return null;
214	  }
215	}
