277	function normalizeCategoria(raw: unknown): string {
278	  if (!raw || typeof raw !== 'string') return 'Outros';
279	  const key = raw.trim().toLowerCase();
280	  if (!key) return 'Outros';
281	
282	  const direct = CATEGORIA_ALIASES[key];
283	  if (direct) return direct;
284	
285	  for (const canonica of CATEGORIAS_NF) {
286	    if (key === canonica.toLowerCase()) return canonica;
